{

"kind": "propose",
"summary": "Adjust probe timeouts for search-api Deployment to prevent premature termination",
"hypotheses": [
    {
        "root_cause_class": "probe_timeout_too_short",
        "summary": "Readiness and liveness probes timeout too quickly for the application's response time",
        "supporting": ["probe_timeouts", "ev-rollout_history", "ev-target_events"],
        "contradicting": [],
        "missing": ["container_logs_tail"],
        "status": "open"
    },
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "Application takes longer to start than probe initial delay or timeout allows",
        "supporting": ["killed_during_startup", "ev-target_events"],
        "contradicting": ["crashed_on_its_own"],
        "missing": ["container_logs_tail"],
        "status": "open"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "search-api",
        "uid": "uid-deployment-search-api"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 10
        },
        "readiness": {
            "timeoutSeconds": 10
        }
    },
    "expected_effect": "Extend probe timeouts to allow application to respond before timing out",
    "rationale": "Current liveness/readiness probe timeouts (1s) are too short for the application's response time, causing premature termination. Increasing to 10s aligns with observed timeout failures and allows the application to respond before probes fail.",
    "cited_evidence_ids": ["probe_timeouts", "ev-rollout_history", "ev-target_events", "ev-pod_states", "ev-target_events"],
    "cited_predicates": ["probe_timeouts", "probe_kills"]
}
}
